140	    /// Use a profile bundle whose calibration manifest has already been
141	    /// validated for online step timing and scheduling.
142	    pub fn with_engine_profile(mut self, profile: LoadedEngineProfile) -> Result<Self> {
143	        profile.validate()?;
144	        self.profile = Some(ProfileConfig { profile });
