172	/// One scheduler, no KV, no LoRA. `partitions` is the frontend-visible engine
173	/// count (tests that declare N engines must spawn N schedulers).
174	pub fn start_engine(config: &SimulatedEngineConfig) -> Engine {
175	    start_engine_with_partitions(config, 1)
176	}
