178	pub fn start_engine_with_partitions(config: &SimulatedEngineConfig, partitions: usize) -> Engine {
179	    assert!(
180	        partitions > 0,
181	        "an engine must expose at least one scheduler"
182	    );
183	    Engine {
184	        schedulers: (0..partitions)
185	            .map(|index| {
186	                spawn_scheduler(
187	                    &format!("pegainfer-sim-{index}"),
188	                    SimScheduler::new(config.clone()),
189	                )
190	            })
191	            .collect(),
192	        info: EngineInfo {
193	            kv_capacity: None,
194	            servable_len: None,
195	        },
196	        lora: None,
197	    }
198	}
