279	struct ProfiledRuntime {
280	    profile: EngineProfile,
281	    worker: WorkerState<RequestId>,
282	    requests: HashMap<RequestId, ProfiledRequest>,
283	    in_flight: Option<ProfiledInFlight>,
284	}
285	
286	struct ProfiledRequest {
287	    completion_tokens: Vec<u32>,
288	    finish_reason: FinishReason,
289	    logprobs: Option<usize>,
290	    prompt_echo: Option<PromptEcho>,
291	}
292	
293	#[derive(Clone, Copy)]
294	struct ProfiledInFlight {
295	    step_id: StepId,
296	    ready_at: Instant,
297	    decode_reqs: usize,
298	}
299	
300	impl ProfiledRuntime {
301	    fn new(config: &ProfileConfig) -> Self {
302	        let worker = WorkerState::new(config.profile.scheduler.clone())
303	            .expect("profile was validated before scheduler construction");
304	        Self {
305	            profile: config.profile.profile.clone(),
306	            worker,
307	            requests: HashMap::new(),
308	            in_flight: None,
309	        }
310	    }
311	
312	    fn step(
313	        &mut self,
314	        config: &SimulatedEngineConfig,
315	        queued: &mut Vec<QueuedRequest>,
316	        ledger: &mut RequestLedger,
317	        spec_decode: &mut Option<SpecDecodeCounters>,
318	        prefix: &mut PrefixCacheTally,
319	    ) -> Result<()> {
320	        self.drain_submissions(config, queued, ledger, prefix)?;
321	        self.cancel_aborted(ledger)?;
322	
323	        if let Some(in_flight) = self.in_flight {
324	            let now = Instant::now();
325	            if in_flight.ready_at > now {
326	                std::thread::sleep((in_flight.ready_at - now).min(WAIT_SLICE));
327	                return Ok(());
328	            }
329	            let outcome = self.worker.complete_step(in_flight.step_id)?;
330	            self.apply_outcome(outcome, in_flight.decode_reqs, config, ledger, spec_decode)?;
331	            self.in_flight = None;
332	            return Ok(());
333	        }
334	
335	        let Some(plan) = self.worker.plan_step()? else {
336	            return Ok(());
337	        };
338	        let step_id = plan.id();
339	        let shape = plan.shape();
340	        let estimate = self.profile.estimate_step(shape)?;
341	        for &request_id in plan.admitted() {
342	            let request = self
343	                .requests
344	                .get_mut(&request_id)
345	                .with_context(|| format!("missing profiled request {request_id}"))?;
346	            ledger.admit(request_id);
347	            if request
348	                .prompt_echo
349	                .as_ref()
350	                .is_some_and(|echo| echo.ids.is_empty())
351	            {
352	                ledger.echo_prompt(
353	                    request_id,
354	                    request
355	                        .prompt_echo
356	                        .take()
357	                        .expect("empty prompt echo was checked above"),
358	                );
359	            }
360	        }
361	        let ready_at = Instant::now()
362	            .checked_add(duration_from_us(estimate.duration_us))
363	            .context("profiled worker step deadline overflow")?;
364	        self.in_flight = Some(ProfiledInFlight {
365	            step_id,
366	            ready_at,
367	            decode_reqs: plan.decode().len(),
368	        });
369	        Ok(())
370	    }
371	
372	    fn drain_submissions(
373	        &mut self,
374	        config: &SimulatedEngineConfig,
375	        queued: &mut Vec<QueuedRequest>,
376	        ledger: &mut RequestLedger,
377	        prefix: &mut PrefixCacheTally,
378	    ) -> Result<()> {
379	        for QueuedRequest { id, request } in std::mem::take(queued) {
380	            if ledger.is_aborted(id) {
381	                ledger.retire(id);
382	                continue;
383	            }
384	            let prompt_tokens = u32::try_from(request.prompt_tokens.len())
385	                .context("profiled request prompt length exceeds u32")?;
386	            let output_token_count = planned_completion_len(config, request.max_tokens);
387	            let output_token_count_u64 = u64::try_from(output_token_count)
388	                .context("profiled output length overflows u64")?;
389	            if let Some(rejection) = self.worker.preflight(prompt_tokens, output_token_count_u64) {
390	                ledger.reject(id, reject_reason(rejection, &request));
391	                continue;
392	            }
393	            // Admitted: the same shared tally the legacy lane uses, so the
394	            // profiled lane does not report zeros for lookups it performed.
395	            prefix.note(config.prefix_cache, &request);
396	            let (mut completion_tokens, finish_reason) =
397	                planned_completion(config, &request.prompt_tokens, request.max_tokens);
398	            completion_tokens.reverse();
399	            let output_tokens =
400	                u32::try_from(completion_tokens.len()).context("profiled output exceeds u32")?;
401	            match self.worker.submit(WorkerRequest {
402	                id,
403	                prompt_tokens,
404	                output_tokens,
405	            })? {
406	                SubmissionResult::Queued => {
407	                    let previous = self.requests.insert(
408	                        id,
409	                        ProfiledRequest {
410	                            completion_tokens,
411	                            finish_reason,
412	                            logprobs: request.logprobs,
413	                            prompt_echo: request
414	                                .prompt_logprobs
415	                                .map(|top_k| logprobs::prompt(&request.prompt_tokens, top_k)),
416	                        },
417	                    );
418	                    ensure!(
419	                        previous.is_none(),
420	                        "profiled request metadata was duplicated"
421	                    );
422	                }
423	                SubmissionResult::Finished => {
424	                    ledger.admit(id);
425	                    if let Some(top_k) = request.prompt_logprobs {
426	                        ledger.echo_prompt(id, logprobs::prompt(&request.prompt_tokens, top_k));
427	                    }
428	                    ledger.finish(id, finish_reason);
429	                }
430	                SubmissionResult::Rejected(rejection) => {
431	                    ledger.reject(id, reject_reason(rejection, &request));
432	                }
433	            }
434	        }
435	        Ok(())
436	    }
437	
438	    fn cancel_aborted(&mut self, ledger: &mut RequestLedger) -> Result<()> {
439	        let ids: Vec<_> = self.requests.keys().copied().collect();
440	        for id in ids {
441	            if !ledger.is_aborted(id) {
442	                continue;
443	            }
444	            match self.worker.cancel(id) {
445	                CancelResult::Cancelled => {
446	                    ledger.retire(id);
447	                    self.requests.remove(&id);
448	                }
449	                CancelResult::Deferred | CancelResult::AlreadyRequested => {}
450	                CancelResult::NotFound => {
451	                    bail!("profiled request {id} disappeared before cancellation")
452	                }
453	            }
454	        }
455	        Ok(())
456	    }
457	
458	    fn apply_outcome(
459	        &mut self,
460	        outcome: StepOutcome<RequestId>,
461	        decode_reqs: usize,
462	        config: &SimulatedEngineConfig,
463	        ledger: &mut RequestLedger,
464	        spec_decode: &mut Option<SpecDecodeCounters>,
465	    ) -> Result<()> {
466	        let mut cancelled = outcome.cancelled;
467	        let generated_ids: Vec<_> = outcome
468	            .generated
469	            .iter()
470	            .map(|token| token.request_id)
471	            .collect();
472	        for request_id in generated_ids {
473	            if ledger.is_aborted(request_id) && !cancelled.contains(&request_id) {
474	                cancelled.push(request_id);
475	            }
476	        }
477	        self.cancel_worker_requests(&cancelled)?;
478	        for &request_id in &cancelled {
479	            if ledger.is_active(request_id) {
480	                ledger.retire(request_id);
481	            }
482	            self.requests.remove(&request_id);
483	        }
484	
485	        for progress in outcome.prefill {
486	            if progress.remaining_tokens != 0 || cancelled.contains(&progress.request_id) {
487	                continue;
488	            }
489	            let request = self
490	                .requests
491	                .get_mut(&progress.request_id)
492	                .with_context(|| format!("missing profiled request {}", progress.request_id))?;
493	            if let Some(prompt_echo) = request.prompt_echo.take() {
494	                ledger.echo_prompt(progress.request_id, prompt_echo);
495	            }
496	        }
497	        for GeneratedToken {
498	            request_id,
499	            token_index,
500	        } in outcome.generated
501	        {
502	            if cancelled.contains(&request_id) {
503	                continue;
504	            }
505	            let request = self
506	                .requests
507	                .get(&request_id)
508	                .with_context(|| format!("missing profiled request {request_id}"))?;
509	            let token_index = token_index
510	                .checked_sub(1)
511	                .context("profiled worker returned an invalid zero token index")?;
512	            let token = *request
513	                .completion_tokens
514	                .get(usize::try_from(token_index).context("token index overflow")?)
515	                .with_context(|| {
516	                    format!("missing token {token_index} for profiled request {request_id}")
517	                })?;
518	            let logprob = request
519	                .logprobs
520	                .map(|top_k| logprobs::completion(token, top_k));
521	            let logprobs = match logprob {
522	                Some(logprob) => vec![Some(logprob)],
523	                None => Vec::new(),
524	            };
525	            ledger.push_tokens(request_id, &[token], &logprobs);
526	        }
527	        for request_id in outcome.finished {
528	            if cancelled.contains(&request_id) {
529	                continue;
530	            }
531	            let request = self
532	                .requests
533	                .remove(&request_id)
534	                .with_context(|| format!("missing profiled request {request_id}"))?;
535	            ledger.finish(request_id, request.finish_reason);
536	        }
537	        if let (Some(counters), Some((k, accepted))) = (spec_decode.as_mut(), config.spec_decode) {
538	            for _ in 0..decode_reqs {
539	                counters.observe_draft(k, accepted);
540	            }
541	        }
542	        Ok(())
543	    }
544	
545	    fn cancel_worker_requests(&mut self, request_ids: &[RequestId]) -> Result<()> {
546	        for &request_id in request_ids {
547	            match self.worker.cancel(request_id) {
548	                // `Cancelled` is the late-abort case: complete_step has
549	                // already cleared the worker's in-flight plan, so the request
550	                // must be removed from running here before its ledger account
551	                // and metadata are retired below.
552	                CancelResult::Cancelled | CancelResult::NotFound => {}
553	                CancelResult::Deferred | CancelResult::AlreadyRequested => {
554	                    bail!("profiled request {request_id} remained in flight during cancellation")
555	                }
556	            }
557	        }
558	        Ok(())
559	    }
560	
561	    fn metrics(&self, spec_decode: Option<&SpecDecodeCounters>) -> SchedulerMetrics {
562	        SchedulerMetrics {
563	            num_running_reqs: self.worker.running_len() as u64,
564	            num_waiting_reqs: self.worker.waiting_len() as u64,
565	            spec_decode: spec_decode.copied(),
566	            ..SchedulerMetrics::default()
567	        }
568	    }
569	}
