571	fn reject_reason(rejection: RequestRejection, request: &Request) -> RejectReason {
572	    match rejection {
573	        RequestRejection::ModelLengthExceeded {
574	            total_tokens: _,
575	            max_model_len,
576	        } => RejectReason::ContextLength {
577	            prompt_tokens: request.prompt_tokens.len(),
578	            max_tokens: request.max_tokens,
579	            limit: max_model_len as usize,
580	        },
581	        RequestRejection::WholePrefillExceedsStepBudget {
582	            prompt_tokens,
583	            max_num_batched_tokens,
584	        } => RejectReason::PrefillStepBudget {
585	            prompt_tokens: prompt_tokens as usize,
586	            limit: max_num_batched_tokens as usize,
587	        },
588	    }
589	}
